        INCLUDE "probe.inc"     ; PROBE_INC, a name
        OUTPUT "probe.bin"
        ORG $4000
start:  db 1, "AB", 3>2, 3<2, low $1234, high $1234
        DUP 2, k                ; k counts from 0
        db $A0 + k
        EDUP
        ALIGN 16
aligned: db $BB
        MACRO TWICE value
        db value, value
        ENDM
        TWICE $77
        ASSERT aligned % 16 == 0, not aligned
        dw $1234, start
        dd $12345678
        ds 3, $55
        DUP 2                   ; no counter
        db $AA
        EDUP
        db PROBE_INC
        ds 2                    ; no fill: zeros
        ALIGN 4, $99            ; a fill of its own
here:   db '#'                  ; a character
        ASSERT $ == here + 1    ; $: this line's address
FIVE    EQU 5
COUNT = 1                       ; a name that may change
COUNT = COUNT + FIVE
        db COUNT
        STRUCT POINT
x       BYTE 1
y       BYTE 2
w       WORD $1234
        ENDS
p1      POINT                           ; the defaults
p2      POINT {7, 8, $ABCD}
        db POINT, POINT.w       ; the size, an offset
        DISP $C000
moved:  dw moved                ; assembled for $C000, stored here
        ENT
after:  dw after
        INCBIN "blob.bin"
        IFNDEF NOWHERE          ; sjasmplus -DNOWHERE would leave it out
        db $CC
        ENDIF
        db $10, #10, 0x10, 10h, 0FFh, %101
        DISPLAY "aligned at ",/H,aligned
        OUTEND
        db $DD                  ; in no file
        OUTPUT "probe.bin", a   ; on at the end of probe.bin
        db $EE
        OUTEND
